package uk.ac.ravensbourne.casevault.common;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.security.SecureRandom; import java.util.*; import org.springframework.core.env.Environment; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
/** Applies nonce-based CSP and browser isolation headers to every response (OWASP ASVS V14). */
@Component public class SecurityHeadersFilter extends OncePerRequestFilter { private final SecureRandom random=new SecureRandom(); private final Environment env; public SecurityHeadersFilter(Environment e){env=e;} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {byte[] b=new byte[16];random.nextBytes(b);String n=Base64.getEncoder().encodeToString(b);r.setAttribute("cspNonce",n);s.setHeader("Content-Security-Policy","default-src 'none'; script-src 'self' 'nonce-"+n+"'; style-src 'self' 'nonce-"+n+"'; img-src 'self' data:; font-src 'self'; connect-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'; object-src 'none'");s.setHeader("X-Content-Type-Options","nosniff");s.setHeader("X-Frame-Options","DENY");s.setHeader("Referrer-Policy","no-referrer");s.setHeader("Permissions-Policy","geolocation=(), microphone=(), camera=()");s.setHeader("Cross-Origin-Opener-Policy","same-origin");s.setHeader("Cross-Origin-Resource-Policy","same-origin");if(Arrays.asList(env.getActiveProfiles()).contains("prod"))s.setHeader("Strict-Transport-Security","max-age=31536000; includeSubDomains");if(r.getUserPrincipal()!=null)s.setHeader("Cache-Control","no-store");c.doFilter(r,s);} }
